test.describe('Users API', () => {
  test('create, read and delete a user', async ({ request }) => {
    // Create
    const created = await request.post('/users', { data: { name: 'Asha', job: 'QA' } });
    expect(created.status()).toBe(201);
    const user = (await created.json()) as User;
    expect(user.name).toBe('Asha');

    // Read: the id from the first call is used in the second
    const fetched = await request.get(`/users/${user.id}`);
    expect(fetched.ok()).toBeTruthy();
    expect(fetched.headers()['content-type']).toContain('application/json');
    expect(await fetched.json()).toMatchObject({ id: user.id, job: 'QA' });

    // Delete
    const removed = await request.delete(`/users/${user.id}`);
    expect(removed.status()).toBe(204);
  });

  test('unknown user returns 404', async ({ request }) => {
    const response = await request.get('/users/999999');
    expect(response.status()).toBe(404);
  });
});

