test('auto-waiting and justified explicit waits', async ({ page }) => {
  await page.goto('/profile');

  // Auto-wait: no wait code needed before these
  await page.getByLabel('City').fill('Bengaluru');
  await page.getByRole('button', { name: 'Save' }).click();
  await expect(page.getByText('Profile saved')).toBeVisible();      // retrying assertion

