  const responsePromise = page.waitForResponse(r => r.url().includes('/api/profile') && r.status() === 200);
  await page.getByRole('button', { name: 'Refresh' }).click();
  const response = await responsePromise;                           // wait for the API call
  expect((await response.json()).city).toBe('Bengaluru');

  await page.getByRole('link', { name: 'Orders' }).click();
  await page.waitForURL('**/orders');                               // wait for navigation

  await expect(page.locator('.spinner')).toBeHidden();              // wait for disappearance

  await expect.poll(async () => {                                   // poll a non-UI condition
    const res = await page.request.get('/api/report/status');
    return (await res.json()).state;
  }, { timeout: 30_000 }).toBe('READY');

