import { test, expect, Page, Locator } from '@playwright/test';

// Dynamic locator: the result card that contains all the given words
function productCard(page: Page, ...words: string[]): Locator {
  let card = page.locator('[data-component-type="s-search-result"]');
  for (const word of words) {
    card = card.filter({ hasText: word });
  }
  return card.filter({ hasNotText: /case|cover/i }).first();
}

// Price located relative to that card
async function priceOf(page: Page, ...words: string[]): Promise<number> {
  const priceText = await productCard(page, ...words)
    .locator('.a-price .a-offscreen')
    .first()
    .textContent();

  return Number((priceText ?? '').replace(/[^0-9.]/g, ''));
}

