// Generic: works for any element type
function unique<T>(values: T[]): T[] {
  return [...new Set(values)];
}

console.log(unique([1, 2, 2, 3, 1, 4]));                    // [1, 2, 3, 4]
console.log(unique(['qa', 'dev', 'qa', 'ops']));            // ['qa', 'dev', 'ops']

// Without Set: filter + indexOf (O(n * n))
function uniqueWithFilter<T>(values: T[]): T[] {
  return values.filter((value, index) => values.indexOf(value) === index);
}
console.log(uniqueWithFilter([5, 5, 6, 7, 6]));             // [5, 6, 7]

// Objects: remove duplicates by a key
interface Product { id: number; name: string; }

function uniqueBy<T, K>(items: T[], key: (item: T) => K): T[] {
  const seen = new Map<K, T>();
  for (const item of items) {
    if (!seen.has(key(item))) {
      seen.set(key(item), item);           // keep the first occurrence
    }
  }
  return [...seen.values()];
}

const products: Product[] = [
  { id: 1, name: 'Backpack' },
  { id: 2, name: 'Bike Light' },
  { id: 1, name: 'Backpack' }
];
console.log(uniqueBy(products, p => p.id));
// [ { id: 1, name: 'Backpack' }, { id: 2, name: 'Bike Light' } ]

